from datetime import datetime, timezone


def parse_expiration(value):
    """Parse an aware ISO-8601 timestamp and normalize it to UTC."""
    parsed = datetime.fromisoformat(value)
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("an explicit timezone offset is required")
    return parsed.astimezone(timezone.utc)


def is_expired(expires_at, now):
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("now must be timezone aware")
    expiration = parse_expiration(expires_at)
    return now.astimezone(timezone.utc) >= expiration


def active_tokens(rows, now):
    return [row["id"] for row in rows if not is_expired(row["expires_at"], now)]
